\label{Theorem Number field analogue Id 220}
Let $\mathbb{F}$ be a number field of degree $d$, $\mathtt{a}_{\mathbb{F}}(m)$, $\Xi_\mathbb{F}(t)$ and $\lambda_{\mathbb{F}}(x)$ as defined in \eqref{Dedekind zeta}, \eqref{Xi_F(t)} and \eqref{Generalized Lambda}, respectively. For $\operatorname{Re}(x)>0$, define
\begin{align}\label{G(x) for no field}
G_{\mathbb{F}}(x) &= \sqrt{x}\left\{\sum_{m=1}^{\infty}\mathtt{a}_{\mathbb{F}}(m)\lambda_{\mathbb{F}}(mx) - \mathcal{R}^{(r_2+2)}_1\left(\frac{1}{x}\right)\right\},
\end{align}
where
\begin{align*}
\mathcal{R}^{(r_2+2)}_1(x) &= \frac{1}{(r_2+1)!}\lim_{s\to 1}\frac{\mathrm{d}^{r_2+1}}{\mathrm{d}s^{r_2+1}}\left((s-1)^{r_2+2}\frac{\zeta_\mathbb{F}(s)\zeta_\mathbb{F}(1-s)}{\sin^{d}(\pi s)}x^s\right).
\end{align*}
Then, for any positive real numbers $\alpha$ and $\beta$ satisfying $\alpha\beta=1$, we have the transformation formula
\begin{align}\label{Number field analogue of transformation formula}
&G_{\mathbb{F}}(\alpha) = G_{\mathbb{F}}(\beta) \notag \\
&= \frac{2^{5-5r_1-r_2}}{\sqrt{D}\pi^{\frac{3r_1}{2}+r_2+1}}\int\limits_{0}^{\infty}\bigg|\Xi_\mathbb{F}\left(\frac{t}{2}\right)\Gamma^{r_1}\left(\frac{-1+it}{4}\right)\Gamma^{r_2}\left(\frac{-1+it}{2}\right)\bigg|^2\frac{\cos\left(\frac{t}{2}\log\alpha\right)}{(1+t^2)^{2-r_1-r_2}}\,\mathrm{d}t.
\end{align}

\label{Theorem Number field analogue Id 2nd paper}
Let $\mathbb{F}$ be a number field of degree $d$ and let $k\geq 1$ be an integer. Let $\Omega_\mathbb{F}(s)$, $\mathtt{a}_{\mathbb{F}, k}(n)$, $\mathcal{H}_{\mathbb{F},k}(x)$ and $\tilde{Z}_{r_1, r_2}(x)$ be defined as in \eqref{Omega_F of fnal eqn}, \eqref{Coeff a_k}, \eqref{New W} and \eqref{Defn of Z}, respectively. For positive real numbers $\alpha$ and $\beta$ such that $\alpha\beta=1$, we have
\begin{align}\label{Extended trans formula}
\mathcal{H}_{\mathbb{F}, k}(\alpha) = \mathcal{H}_{\mathbb{F}, k}(\beta) = \frac{(-8)^k}{2\pi}\int\limits_{0}^{\infty}\frac{\Xi_{\mathbb{F}}^{k}\left(\frac{t}{2}\right)}{\left(1 + t^2\right)^{k}} \cos\left(\frac{t}{2}\log\alpha\right)\mathrm{d}t.
\end{align}

\label{Case k=1 mt2}
Let $\mathtt{a}_{\mathbb{F}}(n)$ and $H_\mathbb{F}$ be defined as in \eqref{Dedekind zeta} and \eqref{Class number formula} respectively. Let $\alpha,\beta>0$ satisfy $\alpha\beta=1$. Then,
\begin{align*}
\mathcal{H}_{\mathbb{F}, 1}(\alpha) = \mathcal{H}_{\mathbb{F}, 1}(\beta) = -\frac{4}{\pi}\int\limits_{0}^{\infty}\frac{\Xi_{\mathbb{F}}\left(\frac{t}{2}\right)}{\left(1 + t^2\right)} \cos\left(\frac{t}{2}\log\alpha\right)\mathrm{d}t,
\end{align*}
where
\begin{align*}
\mathcal{H}_{\mathbb{F}, 1}(x) &= \sqrt{x}\sum_{n=1}^{\infty}\mathtt{a}_{\mathbb{F}}(n)\tilde{Z}_{r_1, r_2}\left(\frac{2^{r_2}\pi^{d/2} nx}{\sqrt{D}} \right) + \frac{\sqrt{Dx}H_\mathbb{F}}{(2\pi)^{r_2}}.
\end{align*}

\label{Gen Koshliakov Formula}
Let $\mathbb{F}$ be a number field, $H_\mathbb{F}$ be the residue defined in \eqref{Class number formula}, and let $\gamma_{\mathbb{F}}$ denote the Euler-Kronecker constant of $\mathbb{F}$. Then, for any positive real numbers $\alpha$ and $\beta$ satisfying $\alpha\beta=1$, we have
\begin{align}
\mathcal{H}_{\mathbb{F}, 2}(\alpha) = \mathcal{H}_{\mathbb{F}, 2}(\beta) = \frac{32}{\pi}\int\limits_{0}^{\infty}\frac{\Xi_{\mathbb{F}}^{2}\left(\frac{t}{2}\right)}{\left(1 + t^2\right)^{2}} \cos\left(\frac{t}{2}\log\alpha\right)\mathrm{d}t, \label{Extended number field RK formula}
\end{align}
where
\begin{align*}
\mathcal{H}_{\mathbb{F}, 2}(x) &= \sqrt{x}\sum_{n=1}^\infty \mathtt{a}_{\mathbb{F}, 2}(n)\tilde{Z}_{2r_1, 2r_2}\left(\frac{4^{r_2}\pi^{d} nx}{D} \right) \\
&- \frac{D H_{\mathbb F}^2\sqrt{x}}{(2\pi)^{2r_2}} \left[ 2\gamma_{\mathbb F} +\log\left(\frac{Dx}{\pi^d}\right) -d\gamma -2(r_1+r_2)\log 2\right].
\end{align*}

\label{Series defn of Lambda_F}
Let $\mathbb{F}$ be a number field of degree $d = r_1 + 2r_2$. Then, $\zeta_\mathbb{F}(s)$ satisfies the following asymmetric form of the functional equation:
\begin{align}\label{Asymm fnal eqn for Dedekind zeta}
\zeta_\mathbb{F}(s) = \frac{\sqrt{D}}{2^{r_2}\pi^d}
\left(\frac{(2\pi)^d}{D} \right)^{s}\Gamma^{d}(1-s)\sin^{r_1}\left(\frac{\pi s}{2}\right)\sin^{r_2}(\pi s)\zeta_\mathbb{F}(1-s).
\end{align}

From \eqref{Dedekind zeta functional equation}, we have
\begin{align}\label{Func eqn 2.0}
\zeta_\mathbb{F}(s) = \left( \frac{D}{4^{r_2} \pi^d} \right)^{\frac{1}{2} - s}
\frac{\Gamma^{r_1}\left(\frac{1-s}{2}\right) \Gamma^{r_2}(1-s)}{\Gamma^{r_1}\left(\frac{s}{2}\right) \Gamma^{r_2}(s)}\zeta_\mathbb{F}(1-s).
\end{align}
We use the reflection formula \eqref{Reflection formula} in \eqref{Func eqn 2.0} to obtain
\begin{align*}
\zeta_\mathbb{F}(s) = \left( \frac{D}{4^{r_2} \pi^d} \right)^{\frac{1}{2} - s}\left[\frac{\Gamma\left(\frac{1-s}{2}\right)\Gamma\left(1-\frac{s}{2}\right)}{\pi}\right]^{r_1}\left[\frac{\Gamma^{2}(1-s)}{\pi}\right]^{r_2}\!\sin^{r_1}\left(\frac{\pi s}{2}\right)\sin^{r_2}(\pi s)\zeta_\mathbb{F}(1-s).
\end{align*}
We now employ \eqref{Legendre Duplication Formula} in the last equation to get
\begin{align*}
\zeta_\mathbb{F}(s) = \frac{\sqrt{D}}{2^{r_2}\pi^d}
\left(\frac{(2\pi)^d}{D} \right)^{s}\Gamma^{r_1}\left(1-s\right)\Gamma^{2r_2}(1-s)\sin^{r_1}\left(\frac{\pi s}{2}\right)\sin^{r_2}(\pi s)\zeta_\mathbb{F}(1-s),
\end{align*}
which gives the desired result.

\label{Special integral lemma}
Let $\delta$ be a real number such that $0<\delta<1$ and $\mathbb{F}$ be a number field of degree $d$. Then, for $0<\operatorname{Re}(y)<1$, we have
\begin{align*}
\lambda_{\mathbb{F}}(y) &= \frac{1}{2\pi i}\int\limits_{(1+\delta)}
\frac{\zeta_\mathbb{F}(1-s)}{\sin^{d}(\pi s)}y^{-s} \mathrm{d}s = R^{(d+1)}_0(y) + R^{(r_2+1)}_1(y) + \sum_{k =1}^\infty R^{(d)}_{-k}(y),
\end{align*}
where the terms $R^{(d+1)}_0(y), R^{(r_2+1)}_1(y)$ and $R^{(d)}_{-k}(y)$ are given by
\begin{align*}
R^{(d+1)}_0(y) &= \frac{1}{d!}\lim_{s \to 0}\frac{\mathrm{d}^{d}}{\mathrm{d}s^{d}}\left(s^{d+1}\frac{\zeta_\mathbb{F}(1-s)}{\sin^{d}(\pi s)}y^{-s} \right),\\
R^{(r_2+1)}_1(y) &= \frac{1}{(r_2)!}\lim_{s\to 1}\frac{\mathrm{d}^{r_2}}{\mathrm{d}s^{r_2}}\left((s-1)^{r_2+1}\frac{\zeta_\mathbb{F}(1-s)}{\sin^{d}(\pi s)}y^{-s} \right), \\
R^{(d)}_{-k}(y) &= \frac{1}{(d-1)!}\lim_{s\to -k}\frac{\mathrm{d}^{d-1}}{\mathrm{d}s^{d-1}}\left((s+k)^{d}\frac{\zeta_\mathbb{F}(1-s)}{\sin^{d}(\pi s)}y^{-s} \right).
\end{align*}

We consider a rectangular contour with vertices $1+\delta - iT, 1+\delta + iT, \alpha +iT$ and $\alpha -iT$, where $\alpha < 0$. By Cauchy's residue theorem, we have
\begin{align*}
\frac{1}{2\pi i}\left( \int\limits_{1+\delta-iT}^{1+\delta +iT} + \int\limits_{1+\delta + iT}^{\alpha +iT} + \int\limits^{\alpha -iT}_{\alpha +iT} + \int\limits_{\alpha -iT}^{1+\delta -iT}\right) \frac{\zeta_\mathbb{F}(1-s)}{\sin^{d}(\pi s)}y^{-s} \mathrm{d}s &= \mathcal{R},
\end{align*}
where $\mathcal{R}$ is the sum of the residues of the integrand function inside the contour. As $T \to \infty$, the horizontal integrals vanish because the exponential decay of $\sin^{-d}(\pi s)$ dominates the polynomial growth of $\zeta_{\mathbb F}(1-s)$. Taking $\alpha \to -\infty$, the left vertical integral likewise vanishes, as $\sin^{-d}(\pi s)$ continues to suppress $\zeta_{\mathbb F}(1-s)$ while $y^{-s}$ decays to zero under the absolute convergence of $\zeta_{\mathbb F}(1-s)$. We now analyse the poles of the integrand function. The Dedekind zeta function $\zeta_{\mathbb F}(1-s)$ has a zero of order $r_1+r_2-1$ at $s=0$ and simple pole at $s=1$. Thus, the integrand has a pole of order $d+1$ at $s=0$, a pole of order $r_2+1$ at $s=1$, and poles of order $d$ at the negative integers. Therefore,
\begin{align*}
\frac{1}{2\pi i}\int\limits_{(1+\delta)}\frac{\zeta_\mathbb{F}(1-s)}{\sin^{d}(\pi s)}y^{-s} \text{d}s &= R^{(d+1)}_0(y) + R^{(r_2+1)}_1(y) + \sum_{k =1}^\infty R^{(d)}_{-k}(y),
\end{align*}
where the terms $R^{(d+1)}_0(y), R^{(r_2+1)}_1(y)$ and $R^{(d)}_{-k}(y)$ are given by
\begin{align*}
R^{(d+1)}_0(y) &= \frac{1}{d!}\lim_{s \to 0}\frac{\text{d}^{d}}{\text{d}s^{d}}\left(s^{d+1}\frac{\zeta_\mathbb{F}(1-s)}{\sin^{d}(\pi s)}y^{-s} \right),\\
R^{(r_2+1)}_1(y) &= \frac{1}{(r_2)!}\lim_{s\to 1}\frac{\mathrm{d}^{r_2}}{\mathrm{d}s^{r_2}}\left((s-1)^{r_2+1}\frac{\zeta_\mathbb{F}(1-s)}{\sin^{d}(\pi s)}y^{-s} \right), \\
R^{(d)}_{-k}(y) &= \frac{1}{(d-1)!}\lim_{s\to -k}\frac{\text{d}^{d-1}}{\text{d}s^{d-1}}\left((s+k)^{d}\frac{\zeta_\mathbb{F}(1-s)}{\sin^{d}(\pi s)}y^{-s} \right).
\end{align*}

Upon taking $\mathbb{F}=\mathbb{Q}$ in the above lemma, we obtain

\begin{align}
\lambda_{\mathbb{Q}}(y) = \frac{1}{2\pi i}\int\limits_{(1+\delta)}
\frac{\zeta(1-s)}{\sin(\pi s)}y^{-s} \mathrm{d}s &= R^{(2)}_0(y) + R_1(y) + \sum_{k =1}^\infty R_{-k}(y), \label{Integral from Titchmarsh unsolved}
\end{align}
where the terms on the right-hand side of \eqref{Integral from Titchmarsh unsolved}
are given by
\begin{align*}
R^{(2)}_0(y) &= \lim_{s \to 0}\frac{\mathrm{d}}{\mathrm{d}s}\left(s^{2}\frac{\zeta(1-s)}{\sin(\pi s)}y^{-s} \right) = \frac{1}{\pi}(\gamma+\log(y)), \\
R_1(y) &= \lim_{s \rightarrow 1} (s-1)\frac{\zeta(1-s)}{\sin(\pi s)}y^{-s} = \frac{1}{2\pi y}, \\
R_{-k}(y) &= \lim_{s \rightarrow -k} (s+n)\frac{\zeta(1-s)}{\sin(\pi s)}y^{-s} = \frac{(-1)^k\zeta(1+k)y^k}{\pi},
\end{align*}
where we have used the series expansions of $\zeta(s)$, $y^{-s}$ and $\frac{1}{\sin(\pi s)}$ to evaluate $R^{(2)}_0(y)$. Substituting the above values of $R^{(2)}_0(y), R_1(y)$ and $R_{-k}(y)$ in \eqref{Integral from Titchmarsh unsolved}, we recover the following classical result from \cite[p.~201, formula~5.74]{Oberhettinger}:
{\allowdisplaybreaks
\begin{align}
\lambda_{\mathbb{Q}}(y) = \frac{1}{2\pi i}\int\limits_{(1+\delta)}
\frac{\zeta(1-s)}{\sin(\pi s)}y^{-s} \mathrm{d}s &= \frac{1}{\pi}(\gamma +\log(y)) + \frac{1}{2\pi y} + \sum_{k=1}^\infty \frac{(-1)^k\zeta(1+k)y^k}{\pi} \notag \\
&= -\frac{1}{\pi}\left(\psi(y+1)- \frac{1}{2y} - \log(y)\right)  \notag \\
&= -\frac{1}{\pi}\left(\psi(y) + \frac{1}{2y} - \log(y)\right) = -\frac{\lambda(y)}{\pi}, \label{Integral from Titchmarsh}
\end{align}}
where $\lambda(y)$ is defined in \eqref{Series Lambda}, and in the last step, we have utilized $\psi(x+1) = \psi(x) + \frac{1}{x}$ \cite[p.~54]{Temme} and the Taylor series expansion $$\psi(x+1) = -\gamma - \sum_{n=1}^{\infty} (-1)^k\zeta(1+k)x^k, \quad |x|<1.$$

[]
Let us define
\begin{align*}
f(t) := \frac{\Xi_{\mathbb{F}}(t)}{\left(\frac{1}{4} + t^2\right)^{2-r_1-r_2}}
\left[\Gamma\!\left(\frac{it}{2}-\frac{1}{4} \right)\Gamma\!\left(-\frac{it}{2}-\frac{1}{4}\right)\right]^{r_1}\!\left[\Gamma\!\left(it-\frac{1}{2}\right)\Gamma\!\left(-it -\frac{1}{2}\right)\right]^{r_2}.
\end{align*}
Considering the function $\phi(s)$ as
\begin{align*}
\phi(s) = \left(\frac{1}{2}+s\right)^{r_1+r_2-2}\sqrt{\xi_{\mathbb{F}}\!\left(\frac{1}{2}-s\right)}\Gamma^{r_1}\!\left(\frac{s}{2}-\frac{1}{4}\right)\Gamma^{r_2}\!\left(s-\frac{1}{2} \right),
\end{align*}
we have $f(t) = \phi(it)\phi(-it)$.
Substituting this into \eqref{Special int} with $y=e^{2z}$ and applying the functional equation $s\Gamma(s) = \Gamma(s+1)$, we obtain
{\allowdisplaybreaks
\begin{align}


&\int\limits_{0}^{\infty}\frac{16\, \Xi_\mathbb{F}^2\left(\frac{t}{2}\right)}{(1+t^2)^{2-r_1-r_2}} \left[\frac{\Gamma\!\left(\frac{it}{4} - \frac{1}{4}\right)\Gamma\!\left(- \frac{it}{4}-\frac{1}{4} \right)}{4}\right]^{r_1}\left[\frac{\Gamma\!\left(\frac{it}{2} - \frac{1}{2}\right)\Gamma\!\left(-\frac{it}{2} - \frac{1}{2}  \right)}{4}\right]^{r_2} \cos(zt)\text{d}t \notag\\
&= \frac{1}{i\sqrt{y}}
\int\limits_{\left(\frac{1}{2}\right)}\frac{(\xi_\mathbb{F}(s))^2}{(-s(s-1))^{2-r_1-r_2}}\left[\Gamma\left(\frac{s-1}{2}\right)\Gamma\left(-\frac{s}{2}\right)\right]^{r_1}\left[\Gamma(-s)\Gamma(s-1)\right]^{r_2} y^s \text{d}s \notag\\
&= \frac{4^{r_1}}{i\sqrt{y}}
\int\limits_{\left(\frac{1}{2}\right)}
\frac{(\xi_\mathbb{F}(s))^2}{(s(s-1))^{2}}
\left[\Gamma\left(\frac{s+1}{2}\right)\Gamma\left(1-\frac{s}{2}\right)\right]^{r_1}\left[\Gamma(1-s)\Gamma(s)\right]^{r_2}
y^s \text{d}s \notag\\
&= \frac{4^{r_1-1}}{i\sqrt{y}}
\int\limits_{\left(\frac{1}{2}\right)}\Bigl[\Gamma\!\left(\frac{s+1}{2}\right)\Gamma\!\left(1-\frac{s}{2}\right)\Gamma^2\!\left(\frac{s}{2}\right)\Bigr]^{r_1}\Bigl[\Gamma(1-s)\Gamma^3(s)\Bigr]^{r_2} 
\zeta_\mathbb{F}^2(s)\left(\frac{yD}{4^{r_2}\pi^d}\right)^s \text{d}s \notag \\
&= \frac{\sqrt{D}\pi^{\frac{3r_1}{2}+r_2}2^{3r_1-r_2}}{4i\sqrt{y}}
\int\limits_{\left(\frac{1}{2}\right)}
\frac{\zeta_\mathbb{F}(s)\zeta_\mathbb{F}(1-s)}{\sin^{d}(\pi s)}y^s \text{d}s, \label{1st integral}
\end{align}}
where in the penultimate step, we invoked \eqref{xi function}, followed by Legendre’s duplication formula \eqref{Legendre Duplication Formula}, Euler’s reflection formula \eqref{Reflection formula} for $\Gamma(s)$, and the asymmetric functional equation \eqref{Asymm fnal eqn for Dedekind zeta} for $\zeta_\mathbb{F}(s)$.
We now denote the integrand in \eqref{1st integral} by
\begin{align*}
I_{\mathbb{F}, y}(s) 
&= \frac{\zeta_\mathbb{F}(s)\zeta_\mathbb{F}(1-s)}{\sin^{d}(\pi s)}y^s.
\end{align*}
To evaluate the integral in \eqref{1st integral}, we shift the line of integration from $\operatorname{Re}(s)=\frac{1}{2}$ to $\operatorname{Re}(s)=1+\delta$, with $\delta\in(0,1)$. This shift introduces a pole of order $r_2+2$ at $s=1$, which must be treated carefully.
Given $T>0$, the residue theorem implies
\begin{align}
\int\limits_{\frac{1}{2}-iT}^{\frac{1}{2}+iT} I_{\mathbb{F}, y}(s) \text{d}s &= \Bigg(
\int\limits_{\frac{1}{2}-iT}^{1+\delta-iT}
+ \int\limits_{1+\delta-iT}^{1+\delta+iT}
+ \int\limits_{1+\delta+iT}^{\frac{1}{2}+iT}
\Bigg)\! I_{\mathbb{F}, y}(s) \text{d}s - 2\pi i\, \mathcal{R}^{(r_2+2)}_1(y),
\label{CRT 1}
\end{align}
where
\begin{align*}
\mathcal{R}^{r_2+2}_1(y) &= \frac{1}{(r_2+1)!}\lim_{s\to 1}\frac{\text{d}^{r_2+1}}{\text{d}s^{r_2+1}}\left((s-1)^{r_2+2}I_{\mathbb{F}, y}(s)\right).
\end{align*}
From the Stirling formula of gamma function, we deduce that the integrals along the horizontal lines from $\frac{1}{2}\pm iT$ to $1\pm \delta+iT$ vanish as $T \rightarrow \infty$.
Now we further simplify the vertical integral from $1+\delta-i\infty$ to $1+\delta+i\infty$ using the series definition \eqref{Dedekind zeta} of $\zeta_\mathbb{F}(s)$ and interchange the integral with the summation due the absolute convergence to have
\begin{align}\label{line integral 1 to delta}
\int\limits_{(1+\delta)} I_{\mathbb{F},y}(s)\text{d}s &= \sum_{m=1}^{\infty}\mathtt{a}_{\mathbb{F}}(m)\lambda_\mathbb{F}\left(\frac{m}{y}\right),
\end{align}
where
\begin{align*}
\lambda_\mathbb{F}\left(\frac{m}{y}\right) &= \int\limits_{(1+\delta)}\frac{\zeta_\mathbb{F}(1-s)}{\sin^{d}(\pi s)}\left(\frac{m}{y}\right)^{-s} \text{d}s.
\end{align*}
Hence substituting the value of \eqref{line integral 1 to delta} in \eqref{CRT 1} with $T \to \infty$ and using the final value of \eqref{CRT 1} in \eqref{1st integral}, we get
\begin{align}\label{The last integral}
&-\frac{2^{6-5r_1-r_2}}{\sqrt{D}\pi^{\frac{3r_1}{2}+r_2}i}\int\limits_{0}^{\infty}\left|\Xi_\mathbb{F}\left(\frac{t}{2}\right)\Gamma^{r_1}\left(\frac{-1+it}{4}\right)\Gamma^{r_2}\left(\frac{-1+it}{2}\right)\right|^2\frac{\cos(zt)}{(1+t^2)^{2-r_1-r_2}}\,\text{d}t \notag \\
&= \frac{2\pi i}{\sqrt{y}}\sum_{m=1}^{\infty}\mathtt{a}_{\mathbb{F}}(m)\lambda_\mathbb{F}\left(\frac{m}{y}\right) - \frac{2\pi i}{\sqrt{y}}\, \mathcal{R}^{(r_2+2)}_1(y),
\end{align}
where
\begin{align*}
\mathcal{R}^{(r_2+2)}_1(y) &= \frac{1}{(r_2+1)!}\lim_{s\to 1}\frac{\text{d}^{r_2+1}}{\text{d}s^{r_2+1}}\left((s-1)^{r_2+2}I_{\mathbb{F}, y}(s)\right).
\end{align*}
In \eqref{The last integral}, we have used the fact that $\overline{\Gamma(s)} = \Gamma(\overline{s})$ and $\Xi_{\mathbb F}(t)$ is real for real values of $t$. Substituting $z=\frac{1}{2}\log\alpha$ into \eqref{The last integral} and observing that $y=e^{2z}=\alpha$ with $\alpha\beta=1$, we get
\begin{align}
& \frac{2^{5-5r_1-r_2}}{\sqrt{D}\pi^{\frac{3r_1}{2}+r_2+1}}\int\limits_{0}^{\infty}\left|\Xi_\mathbb{F}\left(\frac{t}{2}\right)\Gamma^{r_1}\left(\frac{-1+it}{4}\right)\Gamma^{r_2}\left(\frac{-1+it}{2}\right)\right|^2\frac{\cos\left(\frac{t}{2}\log\alpha\right)}{(1+t^2)^{2-r_1-r_2}}\,\text{d}t \notag \\
&= \sqrt{\beta}\left\{\sum_{m=1}^{\infty}\mathtt{a}_{\mathbb{F}}(m)\lambda_\mathbb{F}(m\beta) - \mathcal{R}^{(r_2+2)}_1\left(\frac{1}{\beta}\right)\right\}. \label{Eqn with beta}
\end{align}
Since the left hand side of the above equation is unchanged under the substitution $\alpha \mapsto \beta$, we interchange $\beta$ by $\alpha$ in \eqref{Eqn with beta} and combine it with \eqref{Eqn with beta} to get the desired transformation formula \eqref{Number field analogue of transformation formula}.

[]
Taking $\mathbb{F} = \mathbb{Q}$ in Theorem \ref{Theorem Number field analogue Id 220}, and using \eqref{Integral from Titchmarsh} together with the fact that $\mathtt{a}_{\mathbb{Q}}(m) = 1$, we obtain
\begin{align}\label{Lambda}
\sum_{m=1}^{\infty}\mathtt{a}_{\mathbb{Q}}(m)\lambda_\mathbb{Q}(mx) = -\frac{1}{\pi}\sum_{m=1}^{\infty}\lambda(mx).
\end{align}
Now, we calculate the term $\mathcal{R}^{(r_2+2)}_1\left(\frac{1}{x}\right) = \mathcal{R}^{(2)}_1\left(\frac{1}{x}\right)$ in \eqref{G(x) for no field}, where
\begin{align}
\mathcal{R}^{(2)}_1(x) &= \lim_{s\to 1}\frac{\text{d}}{\text{d}s}\left((s-1)^{2}\frac{\zeta(s)\zeta(1-s)}{\sin(\pi s)}x^s\right).
\end{align}
We use the following Laurent series expansions to find the above residual term.
\begin{align*}
\frac{(s-1)}{\sin(\pi s)} &= -\frac{1}{\pi} - \frac{\pi}{6}(s-1)^2 + \ldots, \\
(s-1)\zeta(s) &= 1 + \gamma(s-1) + \ldots, \\
x^s &= x + x\log(x)(s-1) + \ldots, \\
\zeta(1-s) &= -\frac{1}{2} + \frac{1}{2}\log(2\pi)(s-1) + \ldots.
\end{align*}
Hence, collecting the coefficient of $(s-1)$ in the Laurent series expansion of $(s-1)^{2}\frac{\zeta(s)\zeta(1-s)}{\sin(\pi s)}x^s$, we have
\begin{align}
\mathcal{R}^{(2)}_1(x) &= \frac{x}{2\pi}\left[\gamma - \log\left(\frac{2\pi}{x}\right)\right], \notag \\
\Rightarrow \mathcal{R}^{(2)}_1\left(\frac{1}{x}\right) &=  \frac{1}{2\pi x}\left[\gamma - \log(2\pi x)\right].\label{Res for Q}
\end{align}
Hence, substituting the value of \eqref{Lambda} and \eqref{Res for Q} in Theorem \ref{Theorem Number field analogue Id 220}, we get the desired identity \eqref{Id 220}.

[]
Let us define 
\begin{align*}
f(t) := \frac{2^k\Xi_{\mathbb{F}}^{k-1}(t)}{\left(\frac{1}{4} + t^2\right)^{k}}.
\end{align*}
We know that $f(t) = \phi(it)\phi(-it)$, so we have
\begin{align*}
\phi(s) = \frac{2^{\frac{k}{2}}\xi_{\mathbb{F}}^{\frac{k-1}{2}}\left(\frac{1}{2}-s\right)}{\left(\frac{1}{2} + s\right)^{\frac{k}{2}}\left(\frac{1}{2} - s\right)^{\frac{k}{2}}},
\end{align*}
where $\xi_{\mathbb{F}}(s)$ is defined in \eqref{xi function}. Substituting the above value of $\phi(s)$ in \eqref{Special int} with $y=e^{2z}$, we obtain
{\allowdisplaybreaks
\begin{align}
\int\limits_{0}^{\infty}\frac{2^{3k}\Xi_{\mathbb{F}}^{k}\left(\frac{t}{2}\right)}{\left(1 + t^2\right)^{k}} \cos(zt)\text{d}t 
&= \frac{1}{i\sqrt{y}}
\int\limits_{\left(\frac{1}{2}\right)}\frac{2^k\left[\xi_\mathbb{F}(1-s)\xi_\mathbb{F}(s)\right]^{\frac{k-1}{2}}}{s^k(1-s)^k} \xi_\mathbb{F}(s) y^s \text{d}s \notag\\
&= \frac{1}{i\sqrt{y}}
\int\limits_{\left(\frac{1}{2}\right)}\left(\frac{2\xi_\mathbb{F}(s)}{s(1-s)}\right)^k y^s \text{d}s \notag\\
&= \frac{(-1)^k}{i\sqrt{y}}
\int\limits_{\left(\frac{1}{2}\right)} \Omega_\mathbb{F}^k(s)y^s \text{d}s,
\label{1st integral I1}
\end{align}}
where in the penultimate step, we invoked \eqref{xi function}. To solve the above integral in \eqref{1st integral I1}, we shift the line of integration from $\operatorname{Re}(s)=\frac{1}{2}$ to $\operatorname{Re}(s)=1+\delta$, with $\delta\in(0,1)$. This shift introduces a pole of order $k$ at $s=1$, which must be treated carefully. Let $T>0$, the residue theorem implies 
\begin{align*}
\int\limits_{\frac{1}{2}-iT}^{\frac{1}{2}+iT} \Omega_\mathbb{F}^k(s)y^s \text{d}s &= \Bigg(
\int\limits_{\frac{1}{2}-iT}^{1+\delta-iT}
+ \int\limits_{1+\delta-iT}^{1+\delta+iT}
+ \int\limits_{1+\delta+iT}^{\frac{1}{2}+iT}
\Bigg)\! \Omega_\mathbb{F}^k(s)y^s \text{d}s - 2\pi i\, R^{(k)}_1(y),
\end{align*}
where
\begin{align*}
R^{(k)}_1(y) &= \frac{1}{(k-1)!}\lim_{s\to 1}\frac{\text{d}^{k-1}}{\text{d}s^{k-1}}\left((s-1)^{k}\Omega_\mathbb{F}^k(s)y^s \right).
\end{align*}
The horizontal integrals vanish as $T \rightarrow \infty$ due to the Stirling formula for the gamma factors in the integrand and we are left with
\begin{align}\label{After T infinity}
\int\limits_{\left(\frac{1}{2}\right)}\Omega_\mathbb{F}^k(s)y^s \text{d}s = \int\limits_{\left(1+\delta\right)}\Omega_\mathbb{F}^k(s)y^s \text{d}s - 2\pi i\, R^{(k)}_1(y).
\end{align}
Note that the integral on the right hand side has been evaluated by the author and Maji \cite[p.~14]{BM2}, and can be written as
\begin{align}\label{Half integral value}
\int\limits_{\left(1+\delta\right)}\Omega_\mathbb{F}^k(s)y^s \text{d}s = 2\pi i\, S_{\mathbb{F}, k}\left(\frac{1}{y^2}\right),
\end{align}
where $S_{\mathbb{F}, k}(x)$ is given by
\begin{align*}
S_{\mathbb{F}, k}(x) := \sum_{n=1}^{\infty}\mathtt{a}_{\mathbb{F}, k}(n)\tilde{Z}_{kr_1, kr_2}\left(\frac{2^{kr_2}\pi^{kd/2} n\sqrt{x}}{\sqrt{D^k}} \right), \quad |\operatorname{Arg}(x)| < \frac{\pi d}{2}.
\end{align*}
Substituting \eqref{Half integral value} in \eqref{After T infinity} and then using the final value of the integral on the left hand side of \eqref{After T infinity} into \eqref{1st integral I1}, we get
\begin{align*}
\int\limits_{0}^{\infty}\frac{2^{3k}\Xi_{\mathbb{F}}^{k}\left(\frac{t}{2}\right)}{\left(1 + t^2\right)^{k}} \cos(zt)\text{d}t &= \frac{(-1)^k 2\pi}{\sqrt{y}}\left(S_{\mathbb{F}, k}\left(\frac{1}{y^2}\right) - R^{(k)}_1(y)\right).
\end{align*}
Substituting $z=\frac{1}{2}\log\alpha$ into the last equation and observing that $y=e^{2z}=\alpha$ with $\alpha\beta=1$, we get
\begin{align}\label{One side with beta}
\frac{(-1)^k}{2\pi}\int\limits_{0}^{\infty}\frac{2^{3k}\Xi_{\mathbb{F}}^{k}\left(\frac{t}{2}\right)}{\left(1 + t^2\right)^{k}} \cos\left(\frac{t}{2}\log\alpha\right)\text{d}t &= \sqrt{\beta}\left(S_{\mathbb{F}, k}\left(\beta^2\right) - R^{(k)}_1\left(\frac{1}{\beta}\right)\right).
\end{align}
Since the left-hand side of the above equation is invariant under the interchange $\alpha\leftrightarrow\beta$, we replace $\beta$ by $\alpha$ in \eqref{One side with beta} and combine the resulting relation with \eqref{One side with beta}. We also shuffle the residual terms and use $\alpha = \frac{1}{\beta}$ to obtain
\begin{align*}
\frac{(-1)^k}{2\pi}\int\limits_{0}^{\infty}\frac{2^{3k}\Xi_{\mathbb{F}}^{k}\left(\frac{t}{2}\right)}{\left(1 + t^2\right)^{k}} \cos\left(\frac{t}{2}\log\alpha\right)\text{d}t &= \sqrt{\alpha}\left(S_{\mathbb{F}, k}\left(\alpha^2\right) + \frac{R^{(k)}_1(\alpha)}{\alpha}\right) \\
&= \sqrt{\beta}\left(S_{\mathbb{F}, k}\left(\beta^2\right) + \frac{R^{(k)}_1(\beta)}{\beta}\right),
\end{align*}
which is the desired identity \eqref{Extended trans formula}.

